const int hallPin = {{hall_pin}};
const int limitPin = {{limit_pin}};
const unsigned long debounceMs = {{debounce_ms}};
volatile unsigned long pulseCount = 0;
volatile unsigned long lastPulse = 0;

void IRAM_ATTR onHall() {
  unsigned long now = millis();
  if (now - lastPulse > debounceMs) {
    pulseCount++;
    lastPulse = now;
  }
}

void setup() {
  Serial.begin(115200);
  pinMode(hallPin, INPUT_PULLUP);
  pinMode(limitPin, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(hallPin), onHall, FALLING);
}

void loop() {
  bool limitHit = digitalRead(limitPin) == LOW;
  Serial.print("pulses="); Serial.print(pulseCount);
  Serial.print(" limit="); Serial.println(limitHit ? 1 : 0);
  delay(500);
}
